197	## Edit 1.4 — `dectc_build_dw_specs` (fwd decl, back-compat overload, body)
198	
199	Generalize all three `spec[9]` to `spec[kDecNumDwSpecs]`, the `wi[9]/bi[9]` literal
200	tables + the `s<8` loop + `spec[8]` head to formulas, and the two `s<9` transpose
201	bind loops. The `8` head index becomes `4*dec::kLayers`.
202	
203	OLD:
204	```
205	__device__ __forceinline__ void dectc_build_dw_specs(
206	        const DecActs& acts, int B, int T, DecDwSpec spec[9],
207	        __nv_bfloat16* dwt_base);
208	
209	// Back-compat overload (scalar path / pre-existing call sites): no transpose
210	// scratch. Forwards with dwt_base=nullptr so dYt/Xt are null and stage==0 runs
211	// the proven lambda gather unchanged.
212	__device__ __forceinline__ void dectc_build_dw_specs(
213	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
214	    dectc_build_dw_specs(acts, B, T, spec, /*dwt_base=*/nullptr);
215	}
216	
217	__device__ __forceinline__ void dectc_build_dw_specs(
218	        const DecActs& acts, int B, int T, DecDwSpec spec[9],
219	        __nv_bfloat16* dwt_base) {
220	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
221	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
222	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
223	    //   head: out_w=28 (out_b=29)
224	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
225	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
226	    for (int s = 0; s < 8; ++s) {
227	        const int li = s / 4, kind = s % 4;
228	        DecDwSpec& sp = spec[s];
229	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
230	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
231	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
232	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
233	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
234	        sp.dY_bias = sp.dY;
235	    }
236	    DecDwSpec& hd = spec[8];
237	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
238	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
239	
240	    // CONTIGUOUS-TRANSPOSE bind (stage==1): pack each weight's dYt[Mpad,K] then
241	    // Xt[Kin,K] into dwt_base via the SAME running-offset walk dec_dw_transpose_elems
242	    // uses (so the kernel offsets == the host carve). On the scalar path (dwt_base
243	    // null / stage==0) leave dYt/Xt null → dectc_dw_run_tile takes the lambda gather.
244	    // #if-guarded (not if-constexpr): the dYt/Xt/t_off fields only EXIST when the
245	    // macro is set, so the scalar default's struct + smem are byte-identical.
246	#if SG_TUNED_DEC_DW_STAGE
247	    if (kDecDwTransposeActive && dwt_base != nullptr) {
248	        int64_t e = 0;
249	        for (int s = 0; s < 9; ++s) {
250	            DecDwSpec& sp = spec[s];
251	            sp.t_off = e;
252	            sp.dYt   = dwt_base + e;                                  // [Mpad, K]
253	            sp.Xt    = dwt_base + e + dec_dw_mpad(sp.Nout) * sp.K;    // [Kin,  K]
254	            e += dec_dw_weight_t_elems(sp.Nout, sp.Kin, sp.K);
255	        }
256	    } else {
257	        for (int s = 0; s < 9; ++s) { spec[s].dYt = nullptr; spec[s].Xt = nullptr; spec[s].t_off = 0; }
258	    }
259	#else
260	    (void)dwt_base;
261	#endif
262	}
263	```
