265	NEW:
266	```
267	__device__ __forceinline__ void dectc_build_dw_specs(
268	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs],
269	        __nv_bfloat16* dwt_base);
270	
271	// Back-compat overload (scalar path / pre-existing call sites): no transpose
272	// scratch. Forwards with dwt_base=nullptr so dYt/Xt are null and stage==0 runs
273	// the proven lambda gather unchanged.
274	__device__ __forceinline__ void dectc_build_dw_specs(
275	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs]) {
276	    dectc_build_dw_specs(acts, B, T, spec, /*dwt_base=*/nullptr);
277	}
278	
279	__device__ __forceinline__ void dectc_build_dw_specs(
280	        const DecActs& acts, int B, int T, DecDwSpec spec[kDecNumDwSpecs],
281	        __nv_bfloat16* dwt_base) {
282	    // dec_layout offsets: see kDecOffsets. Per-layer 12-tensor block (li):
283	    //   weight tidx = 2 + 12*li + {0,2,8,10}[kind] (in_w,out_w,ff0_w,ff2_w), bias +1.
284	    //   head out.weight tidx = 2 + 12*L + 2, bias +1.
285	    // At L=2 these reproduce the old wi {2,4,10,12,14,16,22,24} / bi {3,5,11,13,
286	    // 15,17,23,25} and head {28,29} EXACTLY. 4*L layer specs + 1 head = kDecNumDwSpecs.
287	    for (int s = 0; s < 4 * dec::kLayers; ++s) {
288	        const int li = s / 4, kind = s % 4;
289	        const int woff = (kind == 0) ? 0 : (kind == 1) ? 2 : (kind == 2) ? 8 : 10;
290	        const int wi = 2 + 12 * li + woff;   // weight tensor index
291	        const int bi = wi + 1;               // bias tensor index
292	        DecDwSpec& sp = spec[s];
293	        sp.K = T; sp.grad_off = kDecOffsets[wi]; sp.bias_off = kDecOffsets[bi];
294	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
295	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
296	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
297	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
298	        sp.dY_bias = sp.dY;
299	    }
300	    DecDwSpec& hd = spec[4 * dec::kLayers];   // head spec (was spec[8] at L=2)
301	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
302	    hd.grad_off = kDecOffsets[2 + 12 * dec::kLayers + 2];           // out.weight (28 at L=2)
303	    hd.bias_off = kDecOffsets[2 + 12 * dec::kLayers + 3];           // out.bias   (29 at L=2)
304	    hd.dY_bias = hd.dY;
305	
306	    // CONTIGUOUS-TRANSPOSE bind (stage==1): pack each weight's dYt[Mpad,K] then
307	    // Xt[Kin,K] into dwt_base via the SAME running-offset walk dec_dw_transpose_elems
308	    // uses (so the kernel offsets == the host carve). On the scalar path (dwt_base
309	    // null / stage==0) leave dYt/Xt null → dectc_dw_run_tile takes the lambda gather.
310	    // #if-guarded (not if-constexpr): the dYt/Xt/t_off fields only EXIST when the
311	    // macro is set, so the scalar default's struct + smem are byte-identical.
312	#if SG_TUNED_DEC_DW_STAGE
313	    if (kDecDwTransposeActive && dwt_base != nullptr) {
314	        int64_t e = 0;
315	        for (int s = 0; s < kDecNumDwSpecs; ++s) {
316	            DecDwSpec& sp = spec[s];
317	            sp.t_off = e;
318	            sp.dYt   = dwt_base + e;                                  // [Mpad, K]
319	            sp.Xt    = dwt_base + e + dec_dw_mpad(sp.Nout) * sp.K;    // [Kin,  K]
320	            e += dec_dw_weight_t_elems(sp.Nout, sp.Kin, sp.K);
321	        }
322	    } else {
323	        for (int s = 0; s < kDecNumDwSpecs; ++s) { spec[s].dYt = nullptr; spec[s].Xt = nullptr; spec[s].t_off = 0; }
324	    }
325	#else
326	    (void)dwt_base;
327	#endif
328	}
