1215	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32 → sc.x1.
1216	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * vit::kDff, L.ff0_w,
1217	                                           sc.x1, /*Kin=*/vit::kD, /*Nout=*/vit::kDff SG_VIT_P1_F32_MA_MR, sA, sB);  // dx1_ffn [nrows,d]
1218	        __syncthreads();
1219	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1220	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1221	        __syncthreads();
1222	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β.
1223	        vittc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1224	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1225	        // SAVE residual dr1 into sc.dh (free); da → dY_a (bf16).
1226	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x) {
1227	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1 (saved across attn bwd)
1228	            acts.dY_a[li][(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1229	        }
1230	        __syncthreads();
1231	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1232	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * vit::kD, L.out_w,
1233	                                           sc.work, vit::kD, vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);  // dctx
1234	        __syncthreads();
1235	        // attention bwd (FULL): (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d]
1236	        //   fp32 into work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv (bf16).
1237	        vittc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1238	        for (int idx = threadIdx.x; idx < nrows * 3 * vit::kD; idx += blockDim.x)
1239	            acts.dY_qkv[li][(int64_t)g0 * 3 * vit::kD + idx] = __float2bfloat16(work2[idx]);
1240	        __syncthreads();
1241	        // in_proj dX: dx_in_attn = dqkv @ in_w (output width Kin=d, contract Nout=3d).
1242	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1243	        vittc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * vit::kD, L.in_w,
1244	                                           sc.work, /*Kin=*/vit::kD, /*Nout=*/3 * vit::kD SG_VIT_P1_F32_MA_MR, sA, sB);  // dx_in_attn
1245	        __syncthreads();
1246	        for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1247	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1248	        __syncthreads();
1249	    }
1250	
1251	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 (bf16); the
1252	    //    cls/patch/pos owners (P2) read dh0 by global token row. ──
1253	    for (int idx = threadIdx.x; idx < nrows * vit::kD; idx += blockDim.x)
1254	        acts.dh0[(int64_t)g0 * vit::kD + idx] = __float2bfloat16(sc.dh[idx]);
1255	    __syncthreads();
1256	}
